# Get the last 5 entries to see how it ended
tail -5 /home/david/projects/pi-pos-v1/.pi/maestro/sessions/223/builder-reviewer-builder-2026-05-30T15:27:42.jsonl/*.jsonl | python3 -c "
import sys, json
for line in sys.stdin:
    try:
        d = json.loads(line.strip())
        msg = d.get('message', {})
        content = msg.get('content', [])
        role = msg.get('role', '?')
        stop = d.get('stopReason', '?')

        if role == 'assistant':
            # Get thinking summary and text
            texts = [c for c in content if c.get('type') == 'text']
            thinkings = [c for c in content if c.get('type') == 'thinking']
            tool_calls = [c for c in content if c.get('type') == 'toolCall']

            thinking_text = ''
            for t in thinkings:
                th = t.get('thinking', '')
                if th and len(th) > 100:
                    thinking_text = th[:200] + '...'
                elif th:
                    thinking_text = th

            text_content = texts[0].get('text', '') if texts else ''

            print(f'--- Entry stopReason={stop} ---')
            print(f'Thinking (last): {thinking_text[:150]}...')
            print(f'Text output: {text_content[:200]}')
            if tool_calls:
                tc = tool_calls[-1]
                print(f'Last tool: {tc.get(\"name\", \"?\")}({json.dumps(tc.get(\"arguments\", \"?\"))[:100]})')
        elif role == 'user':
            # This is the tool result - show a summary
            content = msg.get('content', [])
            if isinstance(content, list):
                for c in content:
                    if isinstance(c, dict) and c.get('type') == 'text':
                        print(f'--- User message (tool result) ---')
                        print(c['text'][:300])
    except:
        pass
